//! The CEL differential fuzz (spec §4.2): `fixtures/cel-fuzz.json`, a seeded
//! corpus of random expressions the TS reference answered (`src/cel-fuzz.ts`,
//! regenerated byte for byte by `src/cel-fuzz.test.ts`), replayed through the
//! Rust core. A panic, a different value, error or type fails. Explore more
//! seeds with `bun run ./scripts/cel-fuzz.ts --seed <n> --count <n> --out <f>`
//! and `CEL_FUZZ_CORPUS=<f> cargo test -p eui-core --test cel_fuzz`.

mod support;

use eui_core::cel::{call_expression_function, check_expression, evaluate_expression, parse_timestamp, ExpressionEnv};
use eui_core::json;
use serde_json::{json, Map, Value};
use std::panic::{catch_unwind, AssertUnwindSafe};
use support::{first_diff, fixture};

fn zone(z: &Value) -> impl Fn(f64) -> i32 + Send + Sync + 'static {
    let base = z["offset"].as_i64().unwrap() as i32;
    let steps: Vec<(f64, i32)> = z["transitions"].as_array().unwrap().iter().map(|t| (parse_timestamp(t[0].as_str().unwrap()).unwrap(), t[1].as_i64().unwrap() as i32)).collect();
    move |ms| steps.iter().filter(|(at, _)| ms >= *at).last().map_or(base, |(_, o)| *o)
}

fn differ(got: &Value, want: &Value) -> Option<String> {
    if json::equal(got, want) {
        return None;
    }
    Some(first_diff(&json::canonical(got), &json::canonical(want), "").unwrap_or_else(|| format!("{got} != {want}")))
}

#[test]
fn cel_fuzz_corpus() {
    let corpus = match std::env::var("CEL_FUZZ_CORPUS") {
        Ok(path) => serde_json::from_str::<Value>(&std::fs::read_to_string(&path).unwrap()).unwrap(),
        Err(_) => fixture("cel-fuzz.json"),
    };
    let zones: Map<String, Value> = corpus["zones"].as_object().unwrap().clone();
    let sets = corpus["varSets"].as_array().unwrap();
    let mut failures = Vec::new();
    let cases = corpus["cases"].as_array().unwrap();
    for (i, c) in cases.iter().enumerate() {
        let expr = c["expr"].as_str().unwrap();
        let set = &sets[c["set"].as_u64().unwrap() as usize];
        let vars = set["vars"].as_object().unwrap();
        let types = set["types"].as_object().unwrap();
        let now = parse_timestamp(c["now"].as_str().unwrap());
        let offset = zone(&zones[c["zone"].as_str().unwrap()]);
        let env = ExpressionEnv { now, offset: Some(&offset), max_steps: c.get("maxSteps").and_then(Value::as_u64).map(|s| s as usize) };
        let got = catch_unwind(AssertUnwindSafe(|| match evaluate_expression(expr, vars, &env) {
            Ok(v) => json!({ "value": v }),
            Err(e) => json!({ "error": e }),
        }));
        match got {
            Ok(got) => {
                if let Some(d) = differ(&got, &c["eval"]) {
                    failures.push(format!("case {i} eval `{expr}` (set {}, {} {}): {d}\n    rust {got}\n    ts   {}", c["set"], c["zone"], c["now"], c["eval"]));
                }
            }
            Err(_) => failures.push(format!("case {i} eval `{expr}`: PANIC")),
        }
        let got = catch_unwind(AssertUnwindSafe(|| match check_expression(expr, types) {
            Ok(t) => json!({ "type": t }),
            Err(e) => json!({ "error": e }),
        }));
        match got {
            Ok(got) => {
                if let Some(d) = differ(&got, &c["check"]) {
                    failures.push(format!("case {i} check `{expr}` (set {}): {d}\n    rust {got}\n    ts   {}", c["set"], c["check"]));
                }
            }
            Err(_) => failures.push(format!("case {i} check `{expr}`: PANIC")),
        }
    }
    let calls = corpus["calls"].as_array().unwrap();
    for (i, c) in calls.iter().enumerate() {
        let name = c["call"].as_str().unwrap();
        let args = c["args"].as_object().unwrap();
        let now = parse_timestamp(c["now"].as_str().unwrap());
        let offset = zone(&zones[c["zone"].as_str().unwrap()]);
        let env = ExpressionEnv { now, offset: Some(&offset), max_steps: None };
        match catch_unwind(AssertUnwindSafe(|| call_expression_function(name, args, &env))) {
            Ok(r) => {
                let got = match r {
                    None => json!({ "outside": true }),
                    Some(None) => json!({ "none": true }),
                    Some(Some(v)) => json!({ "value": v }),
                };
                if let Some(d) = differ(&got, &c["result"]) {
                    failures.push(format!("call {i} {name} {}: {d}\n    rust {got}\n    ts   {}", Value::Object(args.clone()), c["result"]));
                }
            }
            Err(_) => failures.push(format!("call {i} {name} {}: PANIC", Value::Object(args.clone()))),
        }
    }
    assert!(failures.is_empty(), "{} of {} cases and {} calls disagree with the TS reference:\n{}", failures.len(), cases.len(), calls.len(), failures.iter().take(60).cloned().collect::<Vec<_>>().join("\n"));
    assert!(cases.len() >= 1000);
}
